	public InsertionOrder removeFromCampaigns( UUID parentId, Campaign removeFrom ) {
	    LOGGER.info("handling RemoveCampaignsFromInsertionOrderEvent " );
	
	    InsertionOrder parentEntity = repository.findById(parentId).get();
	    Campaign child = registry.project( Campaign.class, removeFrom.getCampaignId());
	    
	    parentEntity.getCampaigns().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



